import type {
  ManagedToast,
  ToastOptions,
  ToastContextType,
  ToastProviderProps,
} from "./toast.types";

import React, { useState, useCallback } from "react";
import { useUniqueId } from "@system";

import { ToastContext } from "./hooks/use-toast";
import ToastComponent from "./toast";

export const ToastProvider: React.FC<ToastProviderProps> = ({ children, containerElement }) => {
  const [currentToast, setCurrentToast] = useState<ManagedToast | null>(null);
  const fallbackId = useUniqueId("toast");

  const showToast = useCallback(
    (options: ToastOptions): string => {
      const id = options.id ?? fallbackId;
      const { content, ...restOptions } = options;

      const newToastState: ManagedToast = {
        containerElement: containerElement, // Default from provider
        ...restOptions, // Override from options if present
        id,
        children: <>{content}</>,
        show: true,
      };
      setCurrentToast(newToastState);
      options.onOpenChange?.(true);
      return id;
    },
    [containerElement, fallbackId],
  );

  const removeToast = useCallback((id: string) => {
    setCurrentToast((activeToast) => {
      if (activeToast && activeToast.id === id) {
        const userOnOpenChange = activeToast.onOpenChange;
        userOnOpenChange?.(false);
        return null;
      }
      return activeToast;
    });
  }, []);

  const contextValue: ToastContextType = {
    showToast,
    removeToast,
  };

  return (
    <ToastContext.Provider value={contextValue}>
      {children}
      {currentToast && (
        <ToastComponent
          key={currentToast.id}
          {...currentToast}
          show={true}
          onOpenChange={(isOpen) => {
            if (!isOpen) {
              removeToast(currentToast.id);
            }
          }}
        />
      )}
    </ToastContext.Provider>
  );
};
